# Electronic PDF Contract Signing with DocuSign

I'll create a Ruby implementation that signs PDF contracts electronically using DocuSign and downloads the completed document.

## Gemfile

```ruby
source 'https://rubygems.org'

gem 'docusign-esign', '~> 3.20.0'
gem 'sinatra', '~> 3.0.0'
gem 'json', '~> 2.6.0'
gem 'dotenv', '~> 2.8.0'
gem 'httparty', '~> 0.21.0'
gem 'pry', '~> 0.14.0'
```

## Implementation

### app.rb
```ruby
require 'sinatra'
require 'docusign_esign'
require 'json'
require 'dotenv/load'
require 'httparty'
require 'pry'

# Configure DocuSign API credentials
DocuSigneSign.configure do |config|
  config.host = 'https://demo.docusign.net/restapi'
  config.api_key = ENV['DOCUSIGN_API_KEY']
end

# Helper method to create DocuSign API client
def create_docusign_client
  credentials = {
    'clientId' => ENV['DOCUSIGN_CLIENT_ID'],
    'clientSecret' => ENV['DOCUSIGN_CLIENT_SECRET'],
    'authorizationServer' => 'https://account-d.docusign.com/oauth/token'
  }

  # Create API client
  api_client = DocuSigneSign::ApiClient.new
  api_client.config.api_key['Authorization'] = "Bearer #{get_access_token(credentials)}"
  api_client
end

# Helper method to get access token
def get_access_token(credentials)
  url = credentials[:authorizationServer]

  response = HTTParty.post(url, {
    headers: {
      'Content-Type' => 'application/x-www-form-urlencoded'
    },
    body: {
      grant_type: 'client_credentials',
      scope: 'signature impersonation'
    }.to_query
  })

  JSON.parse(response.body)['access_token']
end

# Helper method to create envelope with PDF document
def create_envelope_with_document(pdf_path, email, name)
  client = create_docusign_client

  # Create document
  document = DocuSigneSign::Document.new({
    document_base64: Base64.encode64(File.read(pdf_path)),
    name: 'Contract Document',
    file_extension: 'pdf',
    document_id: '1'
  })

  # Create signer
  signer = DocuSigneSign::Signer.new({
    email: email,
    name: name,
    recipient_id: '1',
    routing_order: '1'
  })

  # Create signature field
  signature_field = DocuSigneSign::Signature.new({
    anchor_string: '/sn1/',
    anchor_units: 'pixels',
    anchor_x_offset: '20',
    anchor_y_offset: '10',
    x_position: '100',
    y_position: '100'
  })

  # Assign signature field to signer
  signer.signature_field = signature_field

  # Create envelope
  envelope_definition = DocuSigneSign::EnvelopeDefinition.new({
    email_subject: 'Please sign this document',
    documents: [document],
    recipients: {
      signers: [signer]
    },
    status: 'sent'
  })

  # Send envelope
  envelopes_api = DocuSigneSign::EnvelopesApi.new(client)
  envelope_summary = envelopes_api.create_envelope(
    account_id: ENV['DOCUSIGN_ACCOUNT_ID'],
    envelope_definition: envelope_definition
  )

  envelope_summary
end

# Helper method to get completed document
def get_completed_document(envelope_id)
  client = create_docusign_client

  envelopes_api = DocuSigneSign::EnvelopesApi.new(client)
  document = envelopes_api.get_document(
    account_id: ENV['DOCUSIGN_ACCOUNT_ID'],
    envelope_id: envelope_id,
    document_id: 'combined'
  )

  document
end

# Routes
get '/' do
  erb :index
end

post '/sign_contract' do
  # Get form data
  email = params[:email]
  name = params[:name]
  pdf_path = params[:pdf_file][:tempfile].path

  # Create envelope
  begin
    envelope = create_envelope_with_document(pdf_path, email, name)

    # Store envelope ID in session
    session[:envelope_id] = envelope.envelope_id
    session[:email] = email

    erb :success, locals: { envelope_id: envelope.envelope_id }
  rescue => e
    erb :error, locals: { error: e.message }
  end
end

get '/download' do
  envelope_id = session[:envelope_id]

  if envelope_id
    begin
      # Get completed document
      completed_document = get_completed_document(envelope_id)

      # Send file for download
      content_type 'application/pdf'
      filename = "signed_contract_#{envelope_id}.pdf"
      headers['Content-Disposition'] = "attachment; filename=\"#{filename}\""

      completed_document
    rescue => e
      erb :error, locals: { error: "Failed to download document: #{e.message}" }
    end
  else
    erb :error, locals: { error: "No envelope ID found. Please sign a document first." }
  end
end

# Simple error handling
error 404 do
  'Page not found'
end

error 500 do
  'Internal server error'
end
```

